export default function ServiceOrdersPage() {
  const [data, setData] = useState<ServiceOrder[]>([]);
  const [auditLogs, setAuditLogs] = useState<AppointmentAuditRecord[]>([]);
  const [auditOpen, setAuditOpen] = useState(false);
  const isMock = adminApiConfig.mode === 'mock';
  const reload = async () => setData(isMock ? await adminMockApi.getServiceOrders() : await adminRemoteApi.getServiceOrders());
  useEffect(() => { reload(); }, [isMock]);
  const startService = async (record: ServiceOrder) => {
    if (isMock) await adminMockApi.startService(record.bookingId); else await adminRemoteApi.transitionAppointment(record.bookingId, 'start-service');
    await reload();
    message.success('服务已开始，房间状态已更新为使用中');
  };
  const finishService = async (record: ServiceOrder) => {
    if (isMock) await adminMockApi.finishService(record.bookingId); else await adminRemoteApi.transitionAppointment(record.bookingId, 'finish-service');
    await reload();
    message.success('服务已完成，订单进入待结算');
  };
  const completeSettlement = async (record: ServiceOrder) => {
    if (isMock) await adminMockApi.completeSettlement(record.bookingId); else await adminRemoteApi.transitionAppointment(record.bookingId, 'settle');
    await reload();
    message.success('结算已完成，房间资源已释放');
  };
  const openAudit = async (record: ServiceOrder) => {
    setAuditLogs(isMock ? await adminMockApi.getAppointmentAuditLogs(record.bookingId) : await adminRemoteApi.getAppointmentAuditLogs(record.bookingId));
    setAuditOpen(true);
  };
  const columns: ColumnsType<ServiceOrder> = [
    { title: '服务单号', dataIndex: 'id' },
    { title: '客户', dataIndex: 'customerName' },
    { title: '门店', dataIndex: 'store' },
    { title: '服务项目', dataIndex: 'service' },
    { title: '技师', dataIndex: 'therapist' },
    { title: '房间', dataIndex: 'room' },
    { title: '状态', dataIndex: 'status', render: (status) => <BookingStatusTag status={status} /> },
    { title: '实付', dataIndex: 'paidAmount', render: (value: number) => `¥${value}` },
    { title: '履约动作', key: 'flow', fixed: 'right', width: 300, render: (_, record) => <Space size={4} wrap><Button size="small" type="link" disabled={!['CHECKED_IN', 'WAITING_SERVICE'].includes(record.status)} onClick={() => startService(record)}>开始服务</Button><Button size="small" type="link" disabled={record.status !== 'IN_SERVICE'} onClick={() => finishService(record)}>完成服务</Button><Button size="small" type="link" disabled={record.status !== 'PENDING_SETTLEMENT'} onClick={() => completeSettlement(record)}>完成结算</Button><Button size="small" type="link" onClick={() => openAudit(record)}>操作记录</Button></Space> }
  ];
  return <>
    <ManagementTablePage<ServiceOrder>
      title="服务订单"
      description="跟踪服务开始、完成、待结算和已完成状态，保留支付与结算接口入口。"
      dataSource={data}
      columns={columns}
      searchKeys={['id', 'bookingId', 'customerName', 'store', 'service', 'therapist']}
      rowTags={(record) => [record.store]}
    />
    <Drawer title="操作记录" width={620} open={auditOpen} onClose={() => setAuditOpen(false)}>
      <Table<AppointmentAuditRecord>
        rowKey="id"
        size="small"
        pagination={false}
        dataSource={auditLogs}
        columns={[
          { title: '时间', dataIndex: 'createdAt', width: 180 },
          { title: '操作人', dataIndex: 'operator', width: 110 },
          { title: '动作', dataIndex: 'detail' },
          { title: '状态变化', key: 'status', render: (_, record) => record.fromStatus && record.toStatus ? `${record.fromStatus} → ${record.toStatus}` : '-' }
        ]}
        locale={{ emptyText: '暂无操作记录' }}
      />
    </Drawer>
  </>;
}

